<body>
  <main id="app"></main>

  <script>
    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitted: false
    };

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phonePattern = /^\+?[0-9()\-\s.]{7,}$/;

    const validate = (values) => ({
      fullName: values.fullName.trim() ? "" : "Full name is required.",
      email: !values.email.trim()
        ? "Email address is required."
        : emailPattern.test(values.email.trim())
          ? ""
          : "Enter a valid email address.",
      phone: !values.phone.trim()
        ? ""
        : phonePattern.test(values.phone.trim())
          ? ""
          : "Enter a valid phone number."
    });

    const FormField = ({ id, label, type, value, placeholder, helperText, errorText, required, autocomplete }) => `
      <div class="form-field">
        <label for="${id}">${label}${required ? ' <span class="required">*</span>' : ''}</label>
        <input
          id="${id}"
          name="${id}"
          type="${type}"
          value="${value}"
          placeholder="${placeholder}"
          autocomplete="${autocomplete}"
          ${required ? "required" : ""}
          aria-invalid="${errorText ? "true" : "false"}"
          aria-describedby="${id}-helper ${errorText ? `${id}-error` : ""}"
        />
        <small class="helper" id="${id}-helper">${helperText || ""}</small>
        <small class="error" id="${id}-error" aria-live="polite">${errorText || ""}</small>
      </div>
    `;

    const App = () => {
      const errors = validate(state.values);
      const showError = (field) => state.touched[field] || state.submitted;

      return `
        <section class="card" aria-labelledby="support-form-title">
          <div class="card-header">
            <h1 id="support-form-title">Contact Support</h1>
            <p>Send a message and the support team will get back to you as soon as possible.</p>
          </div>
          <form novalidate>
            ${FormField({
              id: "fullName",
              label: "Full name",
              type: "text",
              value: state.values.fullName,
              placeholder: "Jane Doe",
              helperText: "Enter your legal or preferred name.",
              errorText: showError("fullName") ? errors.fullName : "",
              required: true,
              autocomplete: "name"
            })}
            ${FormField({
              id: "email",
              label: "Email address",
              type: "email",
              value: state.values.email,
              placeholder: "jane@example.com",
              helperText: "We’ll use this to reply to your request.",
              errorText: showError("email") ? errors.email : "",
              required: true,
              autocomplete: "email"
            })}
            ${FormField({
              id: "phone",
              label: "Phone number",
              type: "tel",
              value: state.values.phone,
              placeholder: "+1 (555) 123-4567",
              helperText: "Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.",
              errorText: showError("phone") ? errors.phone : "",
              required: false,
              autocomplete: "tel"
            })}
            <div class="actions">
              <button type="submit">Submit request</button>
            </div>
          </form>
        </section>
      `;
    };

    const render = () => {
      document.getElementById("app").innerHTML = App();

      document.querySelectorAll("input").forEach((input) => {
        input.addEventListener("input", (event) => {
          state.values[event.target.name] = event.target.value;
          render();
        });

        input.addEventListener("blur", (event) => {
          state.touched[event.target.name] = true;
          render();
        });
      });

      document.querySelector("form").addEventListener("submit", (event) => {
        event.preventDefault();
        state.submitted = true;

        const errors = validate(state.values);
        if (errors.fullName || errors.email || errors.phone) {
          render();
          return;
        }

        alert("Support request ready to send.");
      });
    };

    render();
  </script>
</body>
</html>
