<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1220;
      --panel: #111a2e;
      --panel-2: #16213a;
      --border: #25314d;
      --text: #e5edf9;
      --muted: #9ca9bf;
      --accent: #7c9cff;
      --accent-strong: #9cb0ff;
      --danger: #ff6b7a;
      --shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
      --radius: 18px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 34%),
        linear-gradient(180deg, #08101d 0%, var(--bg) 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 32px 16px;
    }

    .card {
      width: min(100%, 720px);
      background: rgba(17, 26, 46, 0.9);
      border: 1px solid rgba(124, 156, 255, 0.16);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .card-header {
      padding: 32px 32px 20px;
      background: linear-gradient(180deg, rgba(22, 33, 58, 0.95), rgba(17, 26, 46, 0.92));
      border-bottom: 1px solid rgba(124, 156, 255, 0.1);
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(1.6rem, 3vw, 2.2rem);
      letter-spacing: -0.02em;
    }

    p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      padding: 28px 32px 32px;
    }

    .form-field {
      margin-bottom: 20px;
    }

    label {
      display: block;
      margin-bottom: 8px;
      font-weight: 600;
      color: #f3f7ff;
    }

    .required {
      color: var(--accent);
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      background: var(--panel-2);
      color: var(--text);
      border-radius: 12px;
      padding: 14px 15px;
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #7e8ca7;
    }

    input:focus {
      border-color: rgba(124, 156, 255, 0.85);
      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.15);
    }

    input[aria-invalid="true"] {
      border-color: rgba(255, 107, 122, 0.95);
      box-shadow: 0 0 0 4px rgba(255, 107, 122, 0.14);
    }

    .helper,
    .error {
      display: block;
      margin-top: 8px;
      font-size: 0.92rem;
      line-height: 1.45;
    }

    .helper { color: var(--muted); }
    .error { color: var(--danger); min-height: 1.3em; }

    .actions {
      display: flex;
      justify-content: flex-end;
      padding-top: 8px;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      background: linear-gradient(180deg, var(--accent), #5f7eff);
      color: white;
      font-weight: 700;
      font-size: 1rem;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(95, 126, 255, 0.26);
      transition: transform 0.18s ease, filter 0.18s ease;
    }

    button:hover { transform: translateY(-1px); filter: brightness(1.04); }
    button:active { transform: translateY(0); }

    @media (max-width: 640px) {
      .card-header,
      form {
        padding-left: 20px;
        padding-right: 20px;
      }

      .actions {
        justify-content: stretch;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      submitted: false
    };

    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const phonePattern = /^\+?[0-9()\-\s.]{7,}$/;

    const validate = (values) => ({
      fullName: values.fullName.trim() ? "" : "Full name is required.",
      email: !values.email.trim()
        ? "Email address is required."
        : emailPattern.test(values.email.trim())
          ? ""
          : "Enter a valid email address.",
      phone: !values.phone.trim()
        ? ""
        : phonePattern.test(values.phone.trim())
          ? ""
          : "Enter a valid phone number."
    });

    const createField = ({ id, label, type, placeholder, helperText, required, autocomplete }) => {
      const wrapper = document.createElement("div");
      wrapper.className = "form-field";
      wrapper.innerHTML = `
        <label for="${id}">${label}${required ? ' <span class="required">*</span>' : ""}</label>
        <input
          id="${id}"
          name="${id}"
          type="${type}"
          placeholder="${placeholder}"
          autocomplete="${autocomplete}"
          ${required ? "required" : ""}
          aria-invalid="false"
          aria-describedby="${id}-helper ${id}-error"
        />
        <small class="helper" id="${id}-helper">${helperText || ""}</small>
        <small class="error" id="${id}-error" aria-live="polite"></small>
      `;
      return wrapper;
    };

    const app = document.getElementById("app");
    app.innerHTML = `
      <section class="card" aria-labelledby="support-form-title">
        <div class="card-header">
          <h1 id="support-form-title">Contact Support</h1>
          <p>Send a message and the support team will get back to you as soon as possible.</p>
        </div>
        <form novalidate>
          <div id="fields"></div>
          <div class="actions">
            <button type="submit">Submit request</button>
          </div>
        </form>
      </section>
    `;

    const fieldsRoot = document.getElementById("fields");
    fieldsRoot.append(
      createField({
        id: "fullName",
        label: "Full name",
        type: "text",
        placeholder: "Jane Doe",
        helperText: "Enter your legal or preferred name.",
        required: true,
        autocomplete: "name"
      }),
      createField({
        id: "email",
        label: "Email address",
        type: "email",
        placeholder: "jane@example.com",
        helperText: "We’ll use this to reply to your request.",
        required: true,
        autocomplete: "email"
      }),
      createField({
        id: "phone",
        label: "Phone number",
        type: "tel",
        placeholder: "+1 (555) 123-4567",
        helperText: "Optional. Use a format like +1 (555) 123-4567 or 555-123-4567.",
        required: false,
        autocomplete: "tel"
      })
    );

    const form = app.querySelector("form");
    const fields = Object.fromEntries(
      ["fullName", "email", "phone"].map((name) => [
        name,
        {
          input: document.getElementById(name),
          error: document.getElementById(`${name}-error`)
        }
      ])
    );

    const updateFieldState = (name) => {
      const errors = validate(state.values);
      const shouldShow = state.touched[name] || state.submitted;
      const message = shouldShow ? errors[name] : "";
      const field = fields[name];
      field.input.setAttribute("aria-invalid", message ? "true" : "false");
      field.error.textContent = message;
    };

    const updateAllFieldStates = () => {
      ["fullName", "email", "phone"].forEach(updateFieldState);
    };

    Object.values(fields).forEach(({ input }) => {
      input.addEventListener("input", (event) => {
        state.values[event.target.name] = event.target.value;
        updateFieldState(event.target.name);
      });

      input.addEventListener("blur", (event) => {
        state.touched[event.target.name] = true;
        updateFieldState(event.target.name);
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      state.submitted = true;
      updateAllFieldStates();

      const errors = validate(state.values);
      if (errors.fullName || errors.email || errors.phone) {
        return;
      }

      alert("Support request ready to send.");
    });
  </script>
